    when(currentStateOutput.getCurrentState(TEST_RESOURCE, partition, TEST_INSTANCE)).thenReturn(currentState);
    // Pending message for error partition reset
    Message pendingMessage = mock(Message.class);
    when(pendingMessage.getFromState()).thenReturn(fromState);
    when(pendingMessage.getToState()).thenReturn(toState);
    when(currentStateOutput.getPendingMessage(TEST_RESOURCE, partition, TEST_INSTANCE)).thenReturn(pendingMessage);
    event.addAttribute(AttributeName.CURRENT_STATE.name(), currentStateOutput);
    event.addAttribute(AttributeName.CURRENT_STATE_EXCLUDING_UNKNOWN.name(), currentStateOutput);
