    StateModelDefinition stateModelDefinition = new StateModelDefinition.Builder("TestStateModel").addState("ONLINE", 1).addState("OFFLINE").addState("DROPPED").addState("ERROR").initialState("OFFLINE").addTransition("ERROR", "OFFLINE", 1).addTransition("ONLINE", "OFFLINE", 2).addTransition("OFFLINE", "DROPPED", 3).addTransition("OFFLINE", "ONLINE", 4).build();
    // Set controller data provider to event
    BaseControllerDataProvider cache = mock(BaseControllerDataProvider.class);
    when(cache.getStateModelDef(TaskConstants.STATE_MODEL_NAME)).thenReturn(stateModelDefinition);
    Map<String, LiveInstance> liveInstances = mock(Map.class);
