@Test
public void testUpdateAndFindMessageThreadpool() throws Exception {
    // Using ThreadPoolExecutor interface because it allows counting task number
    ThreadPoolExecutor executor0 = new ThreadPoolExecutor(1, 1, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<Runnable>());
    ThreadPoolExecutor executor1 = new ThreadPoolExecutor(1, 1, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<Runnable>());
    ThreadPoolExecutor executor2 = new ThreadPoolExecutor(1, 1, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<Runnable>());
    class MockStateModelFactory_ResourceName extends StateModelFactory<OnlineOfflineStateModelFactory.OnlineOfflineStateModel> {

        @Override
