    Map<String, List<String>> clusterHealth = customRestClient.getAggregatedStoppableCheck(HTTP_LOCALHOST, ImmutableList.of("n1", "n2", "n3", "n4", "n10"), ImmutableSet.of("n7", "n8"), clusterId, Collections.emptyMap());
    Assert.assertTrue(Arrays.stream(instances).allMatch(clusterHealth::containsKey));
    Assert.assertTrue(Arrays.stream(healthyInstances).allMatch(instance -> clusterHealth.get(instance).isEmpty()));
